# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(intake(digest(fold(shape(raw)))))

